const { candidateId, candidateName, startAtGate, singleGate } = $input.item.json;

if (!candidateId) throw new Error('candidateId is required');

// Define gate order
const gates = [
  { name: 'kalodata', order: 1, label: 'KaloData Trend Discovery' },
  { name: 'amazon', order: 2, label: 'Amazon Demand Proof' },
  { name: 'aliexpress', order: 3, label: 'AliExpress Economics' },
  { name: 'meta_ads', order: 4, label: 'Meta Ads Competition' },
];

let gatesToRun = gates;
if (singleGate) {
  gatesToRun = gates.filter(g => g.name === singleGate);
} else if (startAtGate && startAtGate > 1) {
  gatesToRun = gates.filter(g => g.order >= startAtGate);
}

return [{
  json: {
    candidateId,
    candidateName: candidateName || `Candidate #${candidateId}`,
    gatesToRun,
    currentGateIndex: 0,
  }
}];

// Run the current gate
const data = $input.item.json;
const gate = data.gatesToRun[data.currentGateIndex];

if (!gate) {
  return [{ json: { ...data, _done: true, message: 'All gates completed' } }];
}

// Gate-specific scrape configurations
const gateConfigs = {
  kalodata: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'revenue_30d', threshold: 10000, operator: 'gte', label: '30d revenue >= $10k' },
      { name: 'revenue_30d', threshold: 90000, operator: 'lte', label: '30d revenue <= $90k' },
      { name: 'launch_age_days', threshold: 30, operator: 'lte', label: 'Launched within 30 days' },
    ]
  },
  amazon: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'monthly_sales', threshold: 1000, operator: 'gte', label: '1,000+ monthly sales' },
      { name: 'listing_count', threshold: 2, operator: 'gte', label: 'Multiple listings' },
    ]
  },
  aliexpress: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'profit_margin', threshold: 20, operator: 'gte', label: 'Margin >= $20' },
      { name: 'weight_kg', threshold: 2, operator: 'lte', label: 'Under 2kg' },
    ]
  },
  meta_ads: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'active_ads_count', threshold: 1, operator: 'gte', label: 'Has active ads' },
    ]
  },
};

return [{
  json: {
    ...data,
    currentGate: gate,
    gateConfig: gateConfigs[gate.name] || {},
    _done: false,
  }
}];

// STUB: This is where the actual scraper would run.
// In production, this node would be replaced with an Apify actor call
// or a sub-workflow that runs the appropriate scraper.
//
// For now, we simulate the gate check with placeholder data.
// Each gate should return rawData + pass/fail based on criteria.

const data = $input.item.json;
const gate = data.currentGate;
const config = data.gateConfig;

// TODO: Replace with actual Apify actor calls per gate:
// - kalodata: Run KaloData custom actor
// - amazon: Run Amazon product scraper actor
// - aliexpress: Run AliExpress product scraper actor  
// - meta_ads: Use existing Ad Vault scrape infrastructure

// Placeholder: mark as needing manual data for now
const rawData = {
  gate: gate.name,
  status: 'stub_needs_actor',
  message: `Scraper for ${gate.label} not yet connected. Wire Apify actor here.`,
  candidateName: data.candidateName,
  searchQuery: config.searchQuery,
  timestamp: new Date().toISOString(),
};

// For now, we don't auto-pass/fail — mark as null (not evaluated)
return [{
  json: {
    ...data,
    scrapeResult: rawData,
    gatePassed: null,  // null = not yet evaluated, true = pass, false = fail
    criteriaResults: config.criteria.map(c => ({
      ...c,
      actualValue: null,
      passed: null,
    })),
  }
}];

// Check if gate passed and decide whether to continue
const prevData = $('Run Gate Scraper (STUB)').item.json;
const saveResponse = $input.item.json;

// If gate explicitly failed, stop the pipeline
if (prevData.gatePassed === false) {
  return [{
    json: {
      ...prevData,
      _done: true,
      _stoppedAt: prevData.currentGate.name,
      message: `Pipeline stopped: ${prevData.currentGate.label} gate failed`,
    }
  }];
}

// Move to next gate
const nextIndex = prevData.currentGateIndex + 1;
return [{
  json: {
    candidateId: prevData.candidateId,
    candidateName: prevData.candidateName,
    gatesToRun: prevData.gatesToRun,
    currentGateIndex: nextIndex,
  }
}];

// All gates completed — trigger scoring
const data = $input.item.json;
return [{
  json: {
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    message: data._stoppedAt
      ? `Pipeline stopped at ${data._stoppedAt} gate`
      : 'All gates completed successfully',
    completedAt: new Date().toISOString(),
  }
}];
